window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[5]="\",\"fish_Лещ\":\"data:image/webp;base64,\",\"fish_Голавль\":\"data:image/webp;base64,\",\"fish_Язь\":\"data:image/webp;base64,\",\"fish_Осётр\":\"data:image/webp;base64,\",\"fish_Лосось\":\"data:image/webp;base64,\"},\"activity\":[{\"name\":\"Щука\",\"score\":\"ЛИЧНЫЙ +\",\"desc\":\"Недавний подтверждённый личный результат: 4 рыбы на VIB.\",\"color\":\"green\",\"img\":\"data:image/webp;base64,\"},{\"name\":\"Судак\",\"score\":\"НУЖНЫ ДАННЫЕ\",\"desc\":\"Сезонно интересен, но свежего локального подтверждения по текущему участку пока нет.\",\"color\":\"blue\",\"img\":\"data:image/webp;base64,\"},{\"name\":\"Окунь\",\"score\":\"НУЖНЫ ДАННЫЕ\",\"desc\":\"Не используем общие календарные проценты без свежих локальных сигналов.\",\"color\":\"yellow\",\"img\":\"data:image/webp;base64,\"}],\"fishCatalog\":[{\"name\":\"Бычок-песчаный\",\"kind\":\"Бычковые\",\"summary\":\"Небольшой донный бычок, связанный с песчаным и смешанным грунтом.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Низовья рек, лиманы и пресно-солоноватоводные участки южных бассейнов.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Чаще прилов; специализированная ловля для проекта не приоритетна.\",\"note\":\"Важен как кормовой объект для судака, окуня и других хищников.\",\"image\":\"https://upload.wikimedia.org/wikipedia/commons/3/36/Neogobius_fluviatilis.png\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Прочие и региональные\",\"target_rank\":null,\"aliases\":[\"Бычок-песчаный\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: фотографическая вырезка точного таксона, рыба показана целиком на прозрачном фоне.\",\"scientific_name\":\"Neogobius fluviatilis\",\"image_taxon\":\"Neogobius fluviatilis\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Neogobius_fluviatilis.png\",\"image_license\":\"CC BY-SA 4.0\",\"image_author\":\"Original: Viridiflavus~commonswiki; derivative: Ellicrum\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35\"},{\"name\":\"Вьюн амурский\",\"kind\":\"Вьюновые\",\"summary\":\"Донная вьюновая рыба с вытянутым телом, хорошо приспособленная к мягким грунтам и дефициту кислорода.\",\"regions\":\"Дальний Восток / бассейн Амура или Тихого океана\",\"habitat\":\"Тихие протоки, заболоченные участки, пруды и медленно текущие воды Дальнего Востока.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Целенаправленная ловля низкого приоритета; чаще справочный вид.\",\"note\":\"Для базы важна как элемент донной экосистемы и кормовой цепи.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Misgurnus%20anguillicaudatus.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Прочие и региональные\",\"target_rank\":null,\"aliases\":[\"Вьюн амурский\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: фотография точного таксона из федерального источника США, public domain.\",\"scientific_name\":\"Misgurnus anguillicaudatus\",\"image_taxon\":\"Misgurnus anguillicaudatus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Misgurnus_anguillicaudatus.jpg\",\"image_license\":\"Public domain\",\"image_author\":\"Noel Burkhead\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave4\"},{\"name\":\"Вьюн обыкновенный (мисгурн)\",\"kind\":\"Вьюновые\",\"summary\":\"Донная вьюновая рыба тихих, заиленных и хорошо прогреваемых водоёмов.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Пруды, старицы, канавы, затоны и медленные реки с мягким дном.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Низкий приоритет как спортивный объект; чаще поплавочная ловля или прилов.\",\"note\":\"Для базы важна как элемент донной экосистемы и кормовой цепи.\",\"image\":\"https://upload.wikimedia.org/wikipedia/commons/d/d8/Misgurnus_fossilis.png\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Прочие и региональные\",\"target_rank\":null,\"aliases\":[\"Вьюн обыкновенный (мисгурн)\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: фотографическая вырезка точного таксона, рыба показана целиком на прозрачном фоне.\",\"scientific_name\":\"Misgurnus fossilis\",\"image_taxon\":\"Misgurnus fossilis\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Misgurnus_fossilis.png\",\"image_license\":\"CC BY-SA 4.0\",\"image_author\":\"Original: George Chernilevsky; derivative: Ellicrum\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35\"},{\"name\":\"Голавль\",\"kind\":\"Карповые\",\"summary\":\"Всеядный речной карповый, любящий течение, перекаты, нависающие берега и локальные укрытия.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Реки европейской части России и Кавказа.\",\"season\":\"Преимущественно открытая вода; активность растёт с прогревом, но видоспецифична.\",\"methods\":\"Спиннинг небольшими воблерами/крэнками и металлом; поплавочная ловля и нахлыст — по условиям малой или средней реки.\",\"note\":\"Читать границы струи, перекаты и укрытия; важна осторожная подача.\",\"image\":\"data:image/webp;base64,\",\"status\":\"Расширенная карточка — источник указан\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Хищные пресноводные\",\"target_rank\":null,\"aliases\":[\"Голавль\"],\"image_asset\":\"assets/fish/golavl.webp\",\"image_status\":\"verified_project_illustration\",\"image_note\":\"Видовая иллюстрация визуально проверена для карточки; не использовать для близкого вида автоматически.\",\"scientific_name\":\"Squalius cephalus\",\"image_taxon\":\"Squalius cephalus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"core\",\"image_mode\":\"local\"},{\"name\":\"Голец амурский\",\"kind\":\"Вьюновые\",\"summary\":\"Небольшая придонная рыба быстрых и прохладных водотоков; в современной литературе чаще сибирский голец Barbatula toni.\",\"regions\":\"Дальний Восток / бассейн Амура или Тихого океана\",\"habitat\":\"Ручьи, реки и протоки с каменистым или галечным дном бассейна Амура и Сибири.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Справочный вид, не приоритетный объект ловли.\",\"note\":\"Для базы важна как элемент донной экосистемы и кормовой цепи.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Siberian-loach-Barbatula-toni-collected-from-the-Abashiri-River-Japan.png\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Прочие и региональные\",\"target_rank\":null,\"aliases\":[\"Голец амурский\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: точный Barbatula toni из научной публикации; рыба показана сбоку целиком.\",\"scientific_name\":\"Barbatula toni\",\"image_taxon\":\"Barbatula toni\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"Рабочее имя нормализовано к Barbatula toni; в современной русской литературе чаще используется «сибирский голец».\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Siberian-loach-Barbatula-toni-collected-from-the-Abashiri-River-Japan.png\",\"image_license\":\"CC BY 4.0\",\"image_author\":\"Atsuya Yamamoto, Kota Tabata, Tomohiro Fukushige, Takuya Inoue\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave6\"},{\"name\":\"Голец арктический\",\"kind\":\"Лососёвые\",\"summary\":\"Холодолюбивый лососёвый с проходными, озёрными и речными формами.\",\"regions\":\"Сибирь и северные бассейны\",\"habitat\":\"Арктические бассейны, Кольский полуостров, Сибирь, Дальний Восток.\",\"season\":\"Сезон определяется ходом, температурой и местными правилами.\",\"methods\":\"Спиннинг / специализированные региональные методы\",\"note\":\"Сильно зависит от температуры и конкретной формы популяции.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Salvelinus%20alpinus%20%281%29.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Лососёвые и хариусовые\",\"target_rank\":null,\"aliases\":[\"Голец арктический\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: современная фотография точного таксона высокого разрешения.\",\"scientific_name\":\"Salvelinus alpinus\",\"image_taxon\":\"Salvelinus alpinus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"regional\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Salvelinus_alpinus_(1).jpg\",\"image_license\":\"CC BY-SA 3.0\",\"image_author\":\"Chmee2\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave4\"},{\"name\":\"Горбуша\",\"kind\":\"Лососёвые\",\"summary\":\"Самый массовый тихоокеанский лосось с двухлетним жизненным циклом.\",\"regions\":\"Дальний Восток / бассейн Амура или Тихого океана\",\"habitat\":\"Дальний Восток; также акклиматизирована в ряде северных бассейнов.\",\"season\":\"Сезон определяется ходом, температурой и местными правилами.\",\"methods\":\"Спиннинг / специализированные региональные методы\",\"note\":\"Сезонность хода выражена резко; прошлогодний опыт нельзя переносить без учёта поколения.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Oncorhynchus%20gorbuscha%20%28RFEIMG-0280%29.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Лососёвые и хариусовые\",\"target_rank\":null,\"aliases\":[\"Горбуша\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: высокодетальная идентификационная фотография точного таксона из Regulatory Fish Encyclopedia FDA.\",\"scientific_name\":\"Oncorhynchus gorbuscha\",\"image_taxon\":\"Oncorhynchus gorbuscha\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"regional\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Oncorhynchus_gorbuscha_(RFEIMG-0280).jpg\",\"image_license\":\"Public domain\",\"image_author\":\"The U.S. Food and Drug Administration\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave3\"},{\"name\":\"Густера\",\"kind\":\"Карповые\",\"summary\":\"Стайная донно-придонная рыба, близкая по образу жизни к лещу, но обычно мельче.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Реки, озёра и водохранилища; бровки, поливы и спокойные русловые участки.\",\"season\":\"Преимущественно открытая вода; активность растёт с прогревом, но видоспецифична.\",\"methods\":\"Фидер, донная и поплавочная ловля; тактика строится вокруг прикормленной точки.\",\"note\":\"Карточка будет углубляться по литературе: рельеф, корм, сезон, снасти и полевые признаки.\",\"image\":\"https://upload.wikimedia.org/wikipedia/commons/1/1b/Blicca_bjoerkna.png\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Мирные пресноводные\",\"target_rank\":null,\"aliases\":[\"Густера\"],\"image_asset\":\"assets/fish/gustera.webp\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: фотографическая вырезка точного таксона, рыба показана целиком на прозрачном фоне.\",\"image_reference\":{\"taxon\":\"Blicca bjoerkna\",\"ref\":\"https://commons.wikimedia.org/wiki/Category:Blicca_bjoerkna\"},\"scientific_name\":\"Blicca bjoerkna\",\"image_taxon\":\"Blicca bjoerkna\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"regional\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Blicca_bjoerkna.png\",\"image_license\":\"CC BY-SA 4.0\",\"image_author\":\"Original: Viridiflavus~commonswiki; derivative: Ellicrum\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35\"},{\"name\":\"Жерех\",\"kind\":\"Карповые\",\"summary\":\"Дневной пелагический хищник карпового семейства, часто охотится на струе и у границ течений.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Крупные реки и водохранилища европейской части России.\",\"season\":\"Преимущественно открытая вода; активность растёт с прогревом, но видоспецифична.\",\"methods\":\"Спиннинг / специализированные региональные методы\",\"note\":\"Сильные индикаторы: бой, чайки, косы, перекаты, границы струи и дальний заброс.\",\"image\":\"data:image/webp;base64,\",\"status\":\"Расширенная карточка — источник указан\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Хищные пресноводные\",\"target_rank\":3,\"aliases\":[\"Жерех\"],\"image_asset\":\"assets/fish/zhereh.webp\",\"image_status\":\"verified_project_illustration\",\"image_note\":\"Видовая иллюстрация визуально проверена для карточки; не использовать для близкого вида автоматически. Ручной приоритетный набор v35.\",\"scientific_name\":\"Leuciscus aspius\",\"image_taxon\":\"Leuciscus aspius\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"core\",\"image_mode\":\"local\",\"image_curated\":true,\"image_curation_tier\":\"core_target_local_v35\"},{\"name\":\"Змееголов\",\"kind\":\"Змееголовые\",\"summary\":\"Крупный пресноводный хищник-засадчик Channa argus, способный дышать атмосферным воздухом.\",\"regions\":\"Бассейн Амура и Восточная Азия; в других регионах встречается как интродуцированный вид.\",\"habitat\":\"Пресные стоячие и слабопроточные водоёмы, особенно участки с растительностью и укрытиями.\",\"season\":\"Помесячную шкалу без привязки к региону и температуре воды не задаём.\",\"methods\":\"Спиннинг; поиск в траве и у укрытий. Конкретные приманки и сезонные окна уточнять по региону.\",\"note\":\"Засадный хищник; FishBase отмечает преимущественно рыбный рацион и активность утром и вечером.\",\"image\":\"assets/fish/zmeegolov_hero_user.png\",\"status\":\"Расширенная карточка — источник указан\",\"source_level\":\"Таксономия и биологическое ядро привязаны к FishBase; практическая часть отделена от подтверждённых фактов.\",\"category\":\"Хищные пресноводные\",\"target_rank\":null,\"aliases\":[\"Змееголов\",\"амурский змееголов\"],\"image_asset\":\"assets/fish/zmeegolov_hero_user.png\",\"image_status\":\"user_reference_generated_hero\",\"image_note\":\"Hero-визуал создан в согласованном подводном стиле на основе предоставленного пользователем референса змееголова; рыба показана целиком.\",\"image_reference\":{\"taxon\":\"Channa argus\",\"ref\":\"https://commons.wikimedia.org/wiki/File:Channa_argus_01.jpg\"},\"scientific_name\":\"Channa argus\",\"image_taxon\":\"Channa argus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"regional\",\"image_mode\":\"local\",\"image_source_url\":\"\",\"image_license\":\"project_asset\",\"image_author\":\"user reference + project render\",\"image_curated\":true,\"image_curation_tier\":\"user_hero_v40\"},{\"name\":\"Игла-рыба каспийская (в опреснённых водах)\",\"kind\":\"Игловые\",\"summary\":\"Удлинённая игловая рыба, родственник морских коньков, способная заходить в опреснённые воды.\",\"regions\":\"Каспийский бассейн\",\"habitat\":\"Каспийское море, лагуны, устья и опреснённые прибрежные зоны.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Справочный вид; спортивная ловля не является задачей проекта.\",\"note\":\"Не целевой вид; полезна для понимания состава мелкой кормовой ихтиофауны.\",\"image\":\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%20960%20640%22%3E%0A%3Cdefs%3E%3ClinearGradient%20id%3D%22b%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%0A%3Cstop%20stop-color%3D%22%230b2a43%22/%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%2306131f%22/%3E%3C/linearGradient%3E%3C/defs%3E%0A%3Crect%20width%3D%22960%22%20height%3D%22640%22%20rx%3D%2234%22%20fill%3D%22url%28%23b%29%22/%3E%0A%3Cpath%20d%3D%22M210%20325c120-118%20302-139%20443-48%2035%2022%2064%2048%2088%2074-28%2029-59%2052-94%2071-146%2079-322%2048-438-64-43%2029-86%2044-139%2041%2030-26%2048-51%2059-75-11-25-30-50-59-76%2054-2%2098%2018%20140%2047z%22%0Afill%3D%22none%22%20stroke%3D%22%232b9ddd%22%20stroke-width%3D%2215%22%20opacity%3D%22.78%22/%3E%0A%3Ccircle%20cx%3D%22665%22%20cy%3D%22328%22%20r%3D%2211%22%20fill%3D%22%2378d8ff%22/%3E%0A%3C/svg%3E\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Морские и проходные\",\"target_rank\":null,\"aliases\":[\"Игла-рыба каспийская (в опреснённых водах)\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"commons_exact_taxon_runtime\",\"image_note\":\"Иллюстрация запрашивается в Wikimedia Commons только по точному научному таксону. Если подходящий файл не подтверждается, остаётся нейтральная заглушка.\",\"scientific_name\":\"Syngnathus caspius\",\"image_taxon\":\"Syngnathus caspius\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_exact_taxon\"},{\"name\":\"Калуга\",\"kind\":\"Осетровые\",\"summary\":\"Гигантский дальневосточный осетровый бассейна Амура, способный переходить на питание рыбой.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Амур и его эстуарий.\",\"season\":\"Сезонность будет уточняться по виду и региону.\",\"methods\":\"Не указывать способ до проверки законности добычи\",\"note\":\"Редкий и охраняемый вид; практическая карточка — распознавание, биология, правила.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Huso%20dauricus%20in%20Primorskiy%20Oceanarium%20%28October%202024%29-2.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Осетровые\",\"target_rank\":null,\"aliases\":[\"Калуга\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: современная фотография Huso dauricus в Приморском океанариуме; точный таксон.\",\"scientific_name\":\"Huso dauricus\",\"image_taxon\":\"Huso dauricus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"regional\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Huso_dauricus_in_Primorskiy_Oceanarium_(October_2024)-2.jpg\",\"image_license\":\"CC BY-SA 4.0\",\"image_author\":\"Vyacheslav Bukharov\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave6\"},{\"name\":\"Камбала звездчатая\",\"kind\":\"Камбаловые\",\"summary\":\"Дальневосточная камбала с характерными звёздчатыми бугорками на коже.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Эстуарии, прибрежное мелководье и опреснённые зоны северной части Тихого океана.\",\"season\":\"Сезонность зависит от побережья, приливов и нерестовых перемещений.\",\"methods\":\"Береговая донная ловля; конкретные монтажи и наживки зависят от побережья.\",\"note\":\"Способна заходить в пресную воду; важны грунт, приливы и солёность.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Platichthys%20stellatus.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"category\":\"Морские и проходные\",\"target_rank\":null,\"aliases\":[\"Камбала звездчатая\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: современная фотография точного таксона Platichthys stellatus; рыба показана целиком.\",\"scientific_name\":\"Platichthys stellatus\",\"image_taxon\":\"Platichthys stellatus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"taxonomy_note\":\"\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Platichthys_stellatus.jpg\",\"image_license\":\"Public domain\",\"image_author\":\"Dark jedi requiem\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave5\"},{\"name\":\"Камбала полярная\",\"kind\":\"Камбаловые\",\"summary\":\"Холодолюбивая арктическая камбала, способная заходить в солоноватые устья.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Арктические моря, эстуарии и приустьевые зоны.\",\"season\":\"Сезонность зависит от побережья, приливов и нерестовых перемещений.\",\"methods\":\"Донная морская ловля; для проекта региональный специализированный вид.\",\"note\":\"Не смешивать с речной камбалой: это отдельный таксон с другим ареалом.\",\"image\":\"data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20viewBox%3D%220%200%20960%20640%22%3E%0A%3Cdefs%3E%3ClinearGradient%20id%3D%22b%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%0A%3Cstop%20stop-color%3D%22%230b2a43%22/%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%2306131f%22/%3E%3C/linearGradient%3E%3C/defs%3E%0A%3Crect%20width%3D%22960%22%20height%3D%22640%22%20rx%3D%2234%22%20fill%3D%22url%28%23b%29%22/%3E%0A%3Cpath%20d%3D%22M210%20325c120-118%20302-139%20443-48%2035%2022%2064%2048%2088%2074-28%2029-59%2052-94%2071-146%2079-322%2048-438-64-43%2029-86%2044-139%2041%2030-26%2048-51%2059-75-11-25-30-50-59-76%2054-2%2098%2018%20140%2047z%22%0Afill%3D%22none%22%20stroke%3D%22%232b9ddd%22%20stroke-width%3D%2215%22%20opacity%3D%22.78%22/%3E%0A%3Ccircle%20cx%3D%22665%22%20cy%3D%22328%22%20r%3D%2211%22%20fill%3D%22%2378d8ff%22/%3E%0A%3C/svg%3E\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"taxonomy_note\":\"Добавлена отдельно после разделения исходной строки.\",\"category\":\"Морские и проходные\",\"target_rank\":null,\"aliases\":[\"Камбала полярная\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"commons_exact_taxon_runtime\",\"image_note\":\"Иллюстрация запрашивается в Wikimedia Commons только по точному научному таксону. Если подходящий файл не подтверждается, остаётся нейтральная заглушка.\",\"scientific_name\":\"Liopsetta glacialis\",\"image_taxon\":\"Liopsetta glacialis\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_exact_taxon\"},{\"name\":\"Камбала речная\",\"kind\":\"Камбаловые\",\"summary\":\"Эвригалинная камбала, регулярно заходящая из моря в эстуарии и низовья рек.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Балтийское и другие европейские побережья, лиманы и устья.\",\"season\":\"Сезонность зависит от побережья, приливов и нерестовых перемещений.\",\"methods\":\"Береговая донная ловля натуральными насадками; учитывать прилив, течение и солёность.\",\"note\":\"Искать по донному грунту, солёности и приливно-устьевой динамике.\",\"image\":\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Platichthys%20flesus%201.jpg\",\"status\":\"Базовая карточка — источник указан; неподтверждённая детализация не добавлялась\",\"source_level\":\"Таксономия и текст привязаны к указанному источнику; региональные и сезонные выводы применяются только при наличии достаточных данных.\",\"taxonomy_note\":\"Исходная строка «Камбала речная (полярная)» разделена: речная и полярная камбалы — разные таксоны.\",\"category\":\"Морские и проходные\",\"target_rank\":null,\"aliases\":[\"Камбала речная\"],\"image_asset\":\"assets/fish/fish_pending.svg\",\"image_status\":\"curated_commons_photo\",\"image_note\":\"Ручной отбор: фотография точного таксона Platichthys flesus из Северного моря.\",\"scientific_name\":\"Platichthys flesus\",\"image_taxon\":\"Platichthys flesus\",\"taxonomic_level\":\"species\",\"taxonomy_status\":\"verified_or_standardized_v1\",\"practical_priority\":\"reference\",\"image_mode\":\"commons_curated\",\"image_source_url\":\"https://commons.wikimedia.org/wiki/File:Platichthys_flesus_1.jpg\",\"image_license\":\"CC BY-SA 4.0\",\"image_author\":\"Hans Hillewaert\",\"image_curated\":true,\"image_curation_tier\":\"priority_manual_v35_wave5\"},{\"name\":\"Карась золотой\",\"kind\":\"Карповые\",\"summary\":\"Выносливый карась стоячих и слабопроточных вод, лучше серебряного переносит дефицит кислорода.\",\"regions\":\"Россия и сопредельные бассейны в пределах естественного/интродуцированного ареала вида\",\"habitat\":\"Пруды, озёра, старицы и болотистые водоёмы.\",\"season\":\"Преимущественно открытая вода; активность растёт с прогревом, но видоспецифична.\",\"methods\":\"Фидер / донная / поплавочная ловля по ситуации\",\"note\":\"Лучшие знания — прогрев мелководий, растительность, кислород и сезонная активность.\",\"image\":\"data:image/webp;base64,";